import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerConfig;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.apache.kafka.common.serialization.StringSerializer;

import java.util.Properties;

public class ProductionReadyProducer {
    public static void main(String[] args) {
        Properties props = new Properties();
        props.put(ProducerConfig.BOOTSTRAP_SERVERS_CONFIG, "localhost:9092");
        props.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());
        props.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG, StringSerializer.class.getName());

        // Durability and Ordering
        props.put(ProducerConfig.ACKS_CONFIG, "all");
        props.put(ProducerConfig.ENABLE_IDEMPOTENCE_CONFIG, "true");
        props.put(ProducerConfig.MAX_IN_FLIGHT_REQUESTS_PER_CONNECTION, 5);

        // Throughput and Optimization
        props.put(ProducerConfig.BATCH_SIZE_CONFIG, 65536); // 64 KB
        props.put(ProducerConfig.LINGER_MS_CONFIG, 20);
        props.put(ProducerConfig.COMPRESSION_TYPE_CONFIG, "zstd");

        // Transactions
        props.put(ProducerConfig.TRANSACTIONAL_ID_CONFIG, "order-service-txn-01");

        try (KafkaProducer<String, String> producer = new KafkaProducer<>(props)) {
            producer.initTransactions();

            producer.beginTransaction();
            try {
                producer.send(new ProducerRecord<>("orders-topic", "order-123", "{\"status\":\"CREATED\"}"));
                producer.send(new ProducerRecord<>("audit-topic", "order-123", "Audit: Order 123 created"));
                producer.commitTransaction();
            } catch (Exception e) {
                producer.abortTransaction();
                throw e;
            }
        }
    }
}
